import{_ as n,W as p,s as d,u as c,I as s,ah as l,w as t,Z as i,A as a}from"./chunks/framework.B4JzB-Td.js";import"./chunks/theme.Xs8fIzCW.js";const v=JSON.parse('{"title":"终端基础：在 Linux 中创建文件 | LCTT x X-CMD","titleTemplate":false,"description":"终端基础：在 Linux 中创建文件 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"终端基础：在 Linux 中创建文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"终端基础：在 Linux 中创建文件 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230307.2 ⭐️ Terminal Basics Series 4 Creating Files in Linux","title":"终端基础：在 Linux 中创建文件","tag":"202303"},"relativePath":"202303/20230307.2 ⭐️ Terminal Basics Series 4 Creating Files in Linux.md","filePath":"[post].md"}'),r={name:"202303/20230307.2 ⭐️ Terminal Basics Series 4 Creating Files in Linux.md"};function u(h,e,g,m,f,b){const o=p("Link");return c(),d("div",null,[e[19]||(e[19]=s("h1",{id:"终端基础-在-linux-中创建文件",tabindex:"-1"},[t("终端基础：在 Linux 中创建文件 "),s("a",{class:"header-anchor",href:"#终端基础-在-linux-中创建文件","aria-label":"Permalink to 终端基础：在 Linux 中创建文件"},"​")],-1)),e[20]||(e[20]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202303/20/161045uuejvexqrfrurkwn.jpg",alt:""})],-1)),e[21]||(e[21]=s("p",null,"到目前为止，在这个终端基础系列中，你已经学会了：",-1)),s("ul",null,[s("li",null,[i(o,{href:"https://itsfoss.com/change-directories/"},{default:a(()=>e[0]||(e[0]=[t("更改目录")])),_:1})]),s("li",null,[i(o,{href:"https://itsfoss.com/make-directories/"},{default:a(()=>e[1]||(e[1]=[t("创建新目录")])),_:1})]),s("li",null,[i(o,{href:"https://itsfoss.com/list-directory-content/"},{default:a(()=>e[2]||(e[2]=[t("列出目录内容")])),_:1})])]),e[22]||(e[22]=l('<p>现在让我们学习如何在 Linux 命令行中创建文件。我将简要讨论向文件添加内容。但是，稍后将介绍有关编辑文本文件的详细信息。</p><h3 id="使用-touch-命令创建一个新的空文件" tabindex="-1">使用 touch 命令创建一个新的空文件 <a class="header-anchor" href="#使用-touch-命令创建一个新的空文件" aria-label="Permalink to 使用 touch 命令创建一个新的空文件">​</a></h3><p>使用 <code>touch</code> 命令非常简单。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>touch filename</span></span></code></pre></div><p>切换到你的主目录并创建一个名为 <code>practice_files</code> 的新目录，然后切换到该目录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir practice_files &amp;&amp; cd practice_files</span></span></code></pre></div><blockquote><p>💡 <code>&amp;&amp;</code> 是一种组合两个命令的方法。只有当第一个命令执行成功时，第二个命令才会运行。</p></blockquote><p>现在，创建一个名为 <code>new_file</code> 的新文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>touch new_file</span></span></code></pre></div><p>就是这样。你刚刚创建了一个新的空文件。</p><p>列出目录内容并使用 <code>ls -l</code> 命令检查文件的属性。</p><p><img src="https://itsfoss.com/content/images/2023/03/touch-example.svg" alt="Using touch command to create new files"></p><blockquote><p>💡 <code>touch</code> 命令的最初目的是“触摸”文件并更改其时间戳。如果提供的文件不存在，它会创建一个具有该名称的新文件。</p></blockquote><h3 id="使用-echo-命令创建一个新文件" tabindex="-1">使用 echo 命令创建一个新文件 <a class="header-anchor" href="#使用-echo-命令创建一个新文件" aria-label="Permalink to 使用 echo 命令创建一个新文件">​</a></h3><p>很久以前我就应该向你介绍 <code>echo</code> 命令。迟到总比不到好。<code>echo</code> 命令显示你提供给它的任何内容。因此得名“回声”。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo Hello World</span></span></code></pre></div><p>你可以使用重定向并将输出路由到文件。因此在此过程中创建一个新文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo &quot;Hello World&quot; &gt;&gt; other_new_file</span></span></code></pre></div><p>这样，你将创建一个名为 <code>other_new_file</code> 的新文件，其中包含文本 <code>Hello World</code>。</p><p><img src="https://itsfoss.com/content/images/2023/03/echo-example.svg" alt="Using echo command to create new file"></p><p>请记住，如果提供的文件已经存在，使用 <code>&gt;&gt;</code> 重定向，你将向文件添加一个新行。你也可以使用 <code>&gt;</code> 重定向，但它会替换文件的现有内容。</p><p>更多关于重定向的信息可以在下面的教程中找到。</p>',22)),s("blockquote",null,[s("p",null,[s("strong",null,[i(o,{href:"https://linuxhandbook.com/redirection-linux/?ref=its-foss"},{default:a(()=>e[3]||(e[3]=[t("解释：Linux 中的输入、输出和错误重定向")])),_:1})])])]),e[23]||(e[23]=l('<h3 id="使用-cat-命令创建新文件" tabindex="-1">使用 cat 命令创建新文件 <a class="header-anchor" href="#使用-cat-命令创建新文件" aria-label="Permalink to 使用 cat 命令创建新文件">​</a></h3><p><code>cat</code> 命令的最初目的是连接文件。但是，它主要用于显示文件的内容。</p><p>它还可以使用选项创建新文件并添加内容。为此，你可以使用相同的 <code>&gt;</code> 和 <code>&gt;&gt;</code> 重定向。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat &gt;&gt; another_file</span></span></code></pre></div><p>但是这个将创建一个新文件并允许你向其中添加一些文本。添加文本是可选的。<strong>你可以使用 <code>Ctrl+d</code> 键退出 <code>cat</code> 输入模式。</strong></p><p><img src="https://itsfoss.com/content/images/2023/03/cat-example.svg" alt="Using cat command to create new file"></p><p>同样，附加模式 <code>&gt;&gt;</code> 在文件内容的末尾添加新文本，而覆盖模式 <code>&gt;</code> 用新内容替换现有内容。</p><blockquote><p>🖥️ 使用 <code>ls -l</code> 长列表显示并注意时间戳。现在 <code>touch</code> 文件：</p></blockquote><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>touch other_new_file</span></span></code></pre></div><p>你看到时间戳的区别了吗？</p><h3 id="测试你的知识" tabindex="-1">测试你的知识 <a class="header-anchor" href="#测试你的知识" aria-label="Permalink to 测试你的知识">​</a></h3><p>你已经了解了如何创建新文件。这里有一些简单的练习来练习你刚刚学到的东西。它也包括前几章的一些内容。</p><ul><li>使用 <code>touch</code> 命令创建三个新文件，分别命名为 <code>file1</code>、<code>file2</code> 和 <code>file3</code>。提示：你不需要运行 <code>touch</code> 三次。</li><li>创建一个名为 <code>files</code> 的目录，并在其中创建一个名为 <code>my_file</code> 的文件。</li><li>使用 <code>cat</code> 命令创建一个名为 <code>your_file</code> 的文件，并在其中添加以下文本 “This is your file”。</li><li>使用 <code>echo</code> 命令将新行 “This is our file” 添加到 <code>your_file</code>。</li><li>以相反的时间顺序显示所有文件（请参阅第 3 篇）。现在使用 <code>touch</code> 命令修改 <code>file2</code> 和 <code>file3</code> 的时间戳。现在再次按时间倒序显示内容。</li></ul><p>这很有趣。你正在取得很好的进步。你已在本章中学会了创建新文件。接下来，你将学习如何查看文件的内容。</p><hr>',15)),s("p",null,[e[5]||(e[5]=t("via: ")),i(o,{href:"https://itsfoss.com/create-files/"},{default:a(()=>e[4]||(e[4]=[t("https://itsfoss.com/create-files/")])),_:1})]),s("p",null,[e[10]||(e[10]=t("作者：")),i(o,{href:"https://itsfoss.com/author/abhishek/"},{default:a(()=>e[6]||(e[6]=[t("Abhishek Prakash")])),_:1}),e[11]||(e[11]=t(" 选题：")),i(o,{href:"https://github.com/lkxed/"},{default:a(()=>e[7]||(e[7]=[t("lkxed")])),_:1}),e[12]||(e[12]=t(" 译者：")),i(o,{href:"https://github.com/geekpi"},{default:a(()=>e[8]||(e[8]=[t("geekpi")])),_:1}),e[13]||(e[13]=t(" 校对：")),i(o,{href:"https://github.com/wxy"},{default:a(()=>e[9]||(e[9]=[t("wxy")])),_:1})]),s("p",null,[e[16]||(e[16]=t("本文由 ")),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>e[14]||(e[14]=[t("LCTT")])),_:1}),e[17]||(e[17]=t(" 原创编译，")),i(o,{href:"https://linux.cn/"},{default:a(()=>e[15]||(e[15]=[t("Linux中国")])),_:1}),e[18]||(e[18]=t(" 荣誉推出"))])])}const C=n(r,[["render",u]]);export{v as __pageData,C as default};
